function drivers_json(array $payload,int $status=200):void{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($payload);exit;}
function driver_csv(string $value):string{return '"'.str_replace('"','""',$value).'"';}
function driver_norm($value):string{return strtolower(trim((string)$value));}
function driver_bool($value):bool{return filter_var($value,FILTER_VALIDATE_BOOLEAN);}
function driver_time($value):int{if($value instanceof \Google\Cloud\Core\Timestamp)return $value->get()->getTimestamp();if($value instanceof \DateTimeInterface)return $value->getTimestamp();if(is_numeric($value))return (int)$value<20000000000?(int)$value:(int)floor((int)$value/1000);$time=strtotime((string)$value);return $time?:0;}
function driver_real(array $row):bool{$id=driver_norm($row['uid']??$row['rideId']??$row['ratingId']??'');$email=driver_norm($row['email']??'');$moderation=driver_norm($row['moderationStatus']??'visible');$hidden=($row['isVisible']??true)===false||in_array($moderation,['hidden','deleted'],true);return !str_starts_with($id,'test_')&&!str_contains($email,'test.')&&!driver_bool($row['isDemo']??false)&&!driver_bool($row['isDemoPayment']??false)&&!driver_bool($row['deleted']??$row['isDeleted']??false)&&!$hidden;}
function driver_id(array $row):string{return trim((string)($row['driverId']??$row['driverUid']??$row['assignedDriverId']??$row['driverID']??''));}
function driver_ride_id(array $row):string{return trim((string)($row['rideId']??$row['uid']??$row['rideCode']??''));}
function driver_completed(array $ride):bool{return in_array(driver_norm($ride['status']??$ride['rideStatus']??''),['completed','ride_completed'],true);}
function driver_cancelled(array $ride):bool{$s=driver_norm($ride['status']??$ride['rideStatus']??'');return str_starts_with($s,'cancelled')||str_starts_with($s,'canceled');}
function driver_money(array $row):float{foreach(['finalFare','paidAmount','totalFare','acceptedFare','agreedFare','amount','fare'] as $key)if(isset($row[$key])&&is_numeric($row[$key]))return max(0,(float)$row[$key]);return 0;}
function driver_share(array $row):float{foreach(['driverEarning','driverShare','netEarning','earning','paidToDriver'] as $key)if(isset($row[$key])&&is_numeric($row[$key]))return max(0,(float)$row[$key]);return round(driver_money($row)*.7,2);}
function driver_mask_cnic(string $cnic):string{$d=preg_replace('/\D+/','',$cnic)??'';return strlen($d)>=7?substr($d,0,5).'-*****-'.substr($d,-1):'';}
function driver_location($value):string{if(is_string($value)&&trim($value)!=='')return trim($value);if(is_array($value)){foreach(['address','name','formattedAddress'] as $key)if(trim((string)($value[$key]??''))!=='')return trim((string)$value[$key]);}return 'Location pending';}
function driver_status(array $row):string{if(driver_bool($row['isBlocked']??false))return'blocked';$v=driver_norm($row['verificationStatus']??$row['accountStatus']??'pending');if(in_array($v,['rejected','declined'],true))return'rejected';if(!wow_driver_is_approved($row))return'pending';return driver_bool($row['isOnline']??false)?'active':'offline';}
function driver_verification_state(array $row):string{$v=driver_norm($row['verificationStatus']??$row['verification_status']??'pending');if(in_array($v,['approved','verified'],true))return'fully_verified';if(in_array($v,['rejected','declined'],true))return'documents_rejected';$hasCnic=trim((string)driver_pick($row,['cnicFrontUrl','cnic_front_url','cnicUploadUrl','cnic_upload_url','cnicFileUrl','cnic_file_url'],''))!=='';$hasLicence=trim((string)driver_pick($row,['licenceImageUrl','licence_image_url','licenseImageUrl','license_image_url'],''))!=='';$hasVehicle=trim((string)driver_pick($row,['vehicleNumber','vehicle_number','driverVehicleNumber','driver_vehicle_number','vehicleNo','vehicle_no','numberPlate','number_plate','plateNumber','plate_number','registrationNumber','registration_number'],''))!=='';if(!$hasCnic||!$hasLicence||!$hasVehicle)return'documents_missing';return'partially_verified';}
function driver_doc_status(array $row,string $key,string $url):string{$map=is_array($row['documentVerification']??null)?$row['documentVerification']:[];$stored=driver_norm($map[$key]['status']??$map[$key]??'');if(in_array($stored,['approved','verified','rejected','expired','pending'],true))return $stored==='approved'?'verified':$stored;if($url==='')return'missing';return wow_driver_is_approved($row)?'verified':'pending';}
function driver_doc_url(string $url,string $uid='',string $slot=''):string{if($uid!==''&&$slot!==''&&($url!==''||wow_driver_document_existing_local_file($uid,$slot)!==''))return wow_driver_document_url($uid,$slot);if($url===''||preg_match('#^(https?:)?//#i',$url))return$url;return '../php/'.ltrim($url,'/');}
function driver_rating_value(array $row):?float{foreach(['rating','driverRating','stars','score'] as $key){if(!array_key_exists($key,$row))continue;$n=(float)$row[$key];if(is_numeric($row[$key])&&$n>=1&&$n<=5)return$n;}return null;}
