 $rows=[];$ratingSum=0.0;$ratingCount=0;$summary=['total'=>count($profiles),'online_now'=>0,'pending_approval'=>0,'avg_rating'=>null,'rating_count'=>0];foreach($profiles as $uid=>$profile){$row=driver_row($profile,$ctx['ridesByDriver'][$uid]??[],$ctx['ratingsByDriver'][$uid]??[],$ctx['paymentsByDriver'][$uid]??[]);$rows[]=$row;if($row['is_online'])$summary['online_now']++;if(in_array(driver_norm($row['verification_status']),['pending','under_review','submitted','awaiting_verification'],true)&&!$row['is_approved'])$summary['pending_approval']++;foreach($ctx['ratingsByDriver'][$uid]??[] as $rating){$ratingSum+=(float)$rating['_numeric'];$ratingCount++;}}
